function loadTasks(storage, key) {
  let saved;
  try {
    saved = JSON.parse(storage.getItem(key));
  } catch {
    return [];
  }
  const valid =
    saved !== null &&
    saved.version === 1 &&
    Array.isArray(saved.tasks) &&
    saved.tasks.every((t) => typeof t?.id === "number" && typeof t.title === "string");
  return valid ? saved.tasks : [];
}

