function createMemoryHistory(start) {
  const entries = [start];
  let index = 0;
  return {
    push(path) {
      entries.splice(index + 1, Infinity, path);
      index = entries.length - 1;
    },
    back() {
      if (index > 0) index--;
    },
    forward() {
      if (index < entries.length - 1) index++;
    },
    current: () => entries[index],
  };
}

const h = createMemoryHistory("/tasks");
h.push("/tasks/7");
h.push("/tasks/7/edit");
