function countdown(ticks, ms, onTick, onDone) {
  let left = ticks;
  const id = setInterval(() => {
    onTick(left);
    left--;
    if (left === 0) {
      clearInterval(id);
      onDone();
    }
  }, ms);
  return () => clearInterval(id);
}

